/* Installability and user-controlled updates. No push subscriptions or tracking. */
(()=>{
let installPrompt,registration;
const notice=document.querySelector('#pwa-notice');
function announce(text,label,action){notice.replaceChildren();const span=document.createElement('span');span.textContent=text;notice.append(span);if(label){const b=document.createElement('button');b.textContent=label;b.onclick=action;notice.append(b)}const close=document.createElement('button');close.textContent='×';close.setAttribute('aria-label','Hinweis schließen');close.onclick=()=>notice.hidden=true;notice.append(close);notice.hidden=false}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;document.body.classList.add('can-install')});
window.addEventListener('appinstalled',()=>{installPrompt=null;document.body.classList.remove('can-install');announce('Lerndachs ist installiert. Viel Spaß in deiner Welt!')});
async function install(){document.querySelector('#panel')?.close();if(installPrompt){installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;return}announce('Du kannst Lerndachs über die Installationsfunktion deines Browsers zum Startbildschirm hinzufügen, wenn dein Browser das unterstützt.')}
document.addEventListener('click',e=>{if(e.target.closest('[data-install-app]'))install()});
if('serviceWorker'in navigator&&/^https?:$/.test(location.protocol)){
 navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).then(r=>{
  registration=r;
  const ready=()=>announce('Eine neue Version von Lerndachs ist bereit. Dein Spielstand bleibt gespeichert.','Aktualisieren',()=>{LerndachsJourney.save();if(r.waiting){navigator.serviceWorker.addEventListener('controllerchange',()=>location.reload(),{once:true});r.waiting.postMessage({type:'ACTIVATE_UPDATE'})}else location.reload()});
  if(r.waiting)ready();r.addEventListener('updatefound',()=>{const w=r.installing;w?.addEventListener('statechange',()=>{if(w.state==='installed'&&navigator.serviceWorker.controller)ready()})});
 }).catch(()=>{document.body.dataset.offlineCache='unavailable'});
}
window.LerndachsPWA={install,get registration(){return registration}};
})();

;
/* Only the pupils follow the pointer; world positions and body transforms are untouched. */
(()=>{
'use strict';
let pointer=null,frame=0;
function paint(){frame=0;const pause=document.hidden||document.body.classList.contains('no-motion');
 for(const pupils of document.querySelectorAll('.character-pupils')){
  if(!pointer||pause){pupils.removeAttribute('transform');continue}
  const parent=pupils.parentElement,matrix=parent.getScreenCTM?.();if(!matrix)continue;
  try{const local=new DOMPoint(pointer.x,pointer.y).matrixTransform(matrix.inverse()),box=pupils.getBBox();
   const dx=local.x-(box.x+box.width/2),dy=local.y-(box.y+box.height/2),distance=Math.hypot(dx,dy),strength=Math.min(1,distance/100);
   const x=distance?dx/distance*(pupils.classList.contains('pet-pupils')?2:4.8)*strength:0,y=distance?dy/distance*(pupils.classList.contains('pet-pupils')?2:4.6)*strength:0;
   pupils.setAttribute('transform',`translate(${x.toFixed(3)} ${y.toFixed(3)})`);
  }catch{pupils.removeAttribute('transform')}
 }
}
function schedule(){if(!frame)frame=requestAnimationFrame(paint)}
function follow(e){if(e.pointerType==='touch'&&e.type==='pointermove')return;pointer={x:e.clientX,y:e.clientY};schedule()}
window.addEventListener('pointermove',follow,{passive:true});window.addEventListener('pointerdown',follow,{passive:true});
document.documentElement.addEventListener('pointerleave',()=>{pointer=null;schedule()});window.addEventListener('blur',()=>{pointer=null;schedule()});
document.addEventListener('visibilitychange',()=>{if(document.hidden)pointer=null;schedule()});
new MutationObserver(schedule).observe(document.body,{childList:true,subtree:true,attributes:true,attributeFilter:['class']});
window.LerndachsCharacters=Object.freeze({sync:schedule});
})();

;
/* Settings and grown-up areas share the world's palette and local profile. */
(()=>{
const J=LerndachsJourney,E=LerndachsEvidence,esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const shell=document.createElement('dialog');shell.id='adult-dialog';shell.setAttribute('aria-labelledby','adult-title');shell.innerHTML='<button id="adult-close" aria-label="Bereich schließen">×</button><nav class="adult-tabs" aria-label="Erwachsenenbereich"><button data-adult="settings">Einstellungen</button><button data-adult="tasks">Aufgaben</button><button data-adult="parents">Für Eltern</button><button data-adult="teachers">Für Lehrkräfte</button></nav><div id="adult-content"></div>';document.body.append(shell);
const content=shell.querySelector('#adult-content');let mode='settings';
const subjects=()=>Object.entries(LerndachsCurriculum.sources).map(([id,s])=>({id,label:s.title}));
function open(next='settings'){
 mode=next;document.querySelectorAll('dialog[open]').forEach(d=>{if(d!==shell)d.close()});
 shell.querySelectorAll('[data-adult]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.adult===mode));
 if(mode==='settings')settings();else if(mode==='tasks')window.LerndachsMissionOverview?.render(content);else if(mode==='parents')parents();else window.LerndachsWorksheets?.render(content);
 if(!shell.open)shell.showModal();shell.scrollTop=0;
}
function settings(){const g=Learning.grades[J.profile.grade];content.innerHTML=`<div class="adult-heading"><h2 id="adult-title">Einstellungen</h2><p>Die Klasse bleibt auf diesem Gerät gespeichert. Hier kannst du sie ändern.</p></div><div class="settings-card"><span class="adult-symbol">▦</span><div><h3>${g?.label||'Noch keine Klasse gewählt'}</h3><p>Passende Aufgaben für deinen Lernweg.</p></div><button id="settings-grade">Klasse ändern →</button></div><div class="adult-entry-grid"><button data-adult="tasks"><span>▦</span><strong>Alle Aufgaben</strong><small>Status, Lernziele und jede Aufgabe direkt öffnen.</small></button><button data-adult="parents"><span>♡</span><strong>Für Eltern</strong><small>Lernwege, Fächer und Medienkompetenz im Blick.</small></button><button data-adult="teachers"><span>✎</span><strong>Für Lehrkräfte</strong><small>Aufgaben auswählen und als PDF mitnehmen.</small></button></div><div class="settings-tools"><button id="settings-help">Hilfe zum Spiel</button><button id="settings-reset">Neues Spiel starten</button><button data-install-app>App installieren</button></div><a id="settings-impressum" class="settings-legal" href="impressum.html" target="_blank" rel="noopener">Impressum</a><p class="adult-note">Ein gemeinsamer Lernstand pro Browser. Die Bereiche sind keine getrennten Konten und haben keinen Passwortschutz. Alle Lernbeobachtungen bleiben auf diesem Gerät.</p>`}
function metric(s){return `<span class="level-tag">${s.stage}</span><div class="level-track" aria-label="Lerndachs-Stufe ${s.stage}">${['Entdecken','Üben','Anwenden'].map((x,i)=>`<i class="${['Entdecken','Üben','Anwenden'].indexOf(s.stage)>=i?'lit':''}"></i>`).join('')}</div>`}
function parents(){
 const g=Learning.grades[J.profile.grade],all=subjects().map(x=>({...x,...E.summary(x.id)})),observed=all.reduce((n,s)=>n+s.observed,0),known=all.reduce((n,s)=>n+s.known,0),range=['A als Einstieg','A bis B','B','B bis C','C'][J.profile.grade]||'noch offen';
 const recent=J.profile.evidence.filter(e=>e.grade===J.profile.grade).slice(-6).reverse();
 content.innerHTML=`<div class="adult-heading"><h2 id="adult-title">Für Eltern</h2><p>Ein Blick auf den Lernweg Ihres Kindes – aus den Aufgaben und Versuchen in dieser App.</p></div><div class="parent-stats"><article><strong>${known}</strong><span>Katalogaufgaben gelöst</span></article><article><strong>${observed}</strong><span>mit Detailbeobachtung</span></article><article><strong>${J.profile.evidence.filter(e=>e.grade===J.profile.grade&&!e.errors&&!e.hints).length}</strong><span>ohne Fehlversuch oder Tipp</span></article></div><section class="level-explainer"><h3>Orientierungsrahmen: ${range}</h3><p>Die Klassenwahl bestimmt die Aufgaben. Die Angabe A–C beschreibt nur den groben curricularen Bezug unserer Auswahl; sie ist keine gemessene Niveaustufe Ihres Kindes. Deutsch, Mathematik und die weiteren Fächer haben eigene Anforderungen.</p><p><b>Der Lerndachs-Lernweg:</b> Noch offen = keine Detaildaten. Entdecken = 1–2 verschiedene Lösungen. Üben = ab 3 Lösungen. Anwenden = mindestens 6 Lösungen, davon 80 % ohne Fehlversuch oder Tipp, aus mindestens 3 Lernzielen. Das sind appinterne Hinweise, keine Schulnoten.</p></section><div class="subject-grid">${all.map(s=>`<article class="subject-card"><h3>${s.label}</h3><p>${s.known} / ${s.total} Aufgaben gelöst</p>${metric(s)}<p>${s.observed?`${s.independent} von ${s.observed} beobachteten Lösungen ohne Fehlversuch oder Tipp. ${s.retries} mit erneutem Versuch, ${s.hints} mit Tipp.`:'Noch keine Detailbeobachtungen. Beginnen Sie mit einer gemeinsamen Aufgabe.'}</p>${s.legacy?`<small>${s.legacy} frühere Lösungen ohne Versuchsdaten.</small>`:''}<button data-parent-practice="${s.id}">Gemeinsam entdecken →</button></article>`).join('')}</div><section class="media-report"><h3>Medien sicher nutzen</h3><p>Die Alltagsszenarien orientieren sich an den sechs <a href="${LerndachsMedia.source}" target="_blank" rel="noopener">Kompetenzbereichen der KMK</a>. Richtige Antworten zeigen Wissen in der App; praktische Fertigkeiten im Alltag müssen gemeinsam beobachtet werden.</p><div class="media-grid">${LerndachsMedia.dimensions.map(([id,label])=>{const s=E.summary('media',id);return `<article><strong>${label}</strong><span>${s.known}/${s.total} Szenarien gelöst</span><small>${s.observed?`${s.independent}/${s.observed} ohne Fehlversuch oder Tipp`:'Noch keine Beobachtung'}</small><p>${s.known?'Fragen Sie nach einem Beispiel aus dem Alltag.':'Probieren Sie ein Szenario gemeinsam aus.'}</p></article>`}).join('')}</div></section><section><h3>Zuletzt entdeckt</h3>${recent.length?`<ul class="recent-learning">${recent.map(e=>`<li><span>${esc(e.skill)}</span><small>${new Date(e.at).toLocaleDateString('de-DE')} · ${e.errors?'mit neuem Versuch':e.hints?'mit Tipp':'ohne Fehlversuch oder Tipp'}</small></li>`).join('')}</ul>`:'<p>Neue Lösungen erscheinen hier mit Datum. Frühere Antworten bleiben als Katalogfortschritt erhalten.</p>'}</section><p class="adult-note">Keine standardisierte Diagnostik. Vorlesefunktion, Hilfe außerhalb der App und Zusammenarbeit werden nicht vollständig erfasst. Lernstand dieses Browsers; mehrere Kinder am selben Gerät teilen sich diese Daten.</p>`;
}
shell.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.adult)open(b.dataset.adult);if(b.id==='adult-close')shell.close();if(b.id==='settings-grade'){shell.close();window.dispatchEvent(new Event('request-grade-settings'))}if(b.id==='settings-reset'){if(!confirm('Neues Spiel starten? Deine Sterne, Figuren und Einrichtung werden zurückgesetzt.'))return;const url=new URL(location.href);url.searchParams.set('reset','1');location.assign(url.href)}if(b.id==='settings-help'){shell.close();window.dispatchEvent(new Event('request-world-help'))}if(b.dataset.parentPractice){shell.close();Learning.openSubject(b.dataset.parentPractice)}});
document.querySelector('#help').onclick=()=>open();
window.LerndachsAdults={open,subjects,escape:esc};
})();

;
/* Settings catalogue. Browsing other grades never changes the saved class. */
(()=>{
const P=LerndachsMissionProgress,J=LerndachsJourney,esc=LerndachsAdults.escape;
let filters={grade:J.profile.grade??1,subject:'all',status:'all',difficulty:'all',text:''},page=0,host,lastProfileGrade=J.profile.grade;
const labels={'math':'Mathematik',german:'Deutsch',science:'Sachunterricht',music:'Musik',art:'Kunst',media:'Medien'};
const statuses=['Offen','Begonnen','Mit Hilfe gelöst','Selbstständig gelöst','Mehrfach selbstständig','Früher gelöst'];
function render(node){if(J.profile.grade!==lastProfileGrade){lastProfileGrade=J.profile.grade;filters.grade=lastProfileGrade??1;page=0}host=node;host.innerHTML=`<div class="adult-heading"><h2 id="adult-title">Alle Aufgaben</h2><p>Entdecken, üben, anwenden – jede Mission in deinem Tempo.</p></div><div class="mission-filters"><label>Klassenstufe<select id="mission-grade">${Object.entries(Learning.grades).map(([g,v])=>`<option value="${g}" ${+g===filters.grade?'selected':''}>${v.label}</option>`).join('')}</select></label><label>Fach<select id="mission-subject"><option value="all">Alle Fächer</option>${Object.entries(labels).map(([id,label])=>`<option value="${id}" ${filters.subject===id?'selected':''}>${label}</option>`).join('')}</select></label><label>Status<select id="mission-status"><option value="all">Alle Status</option>${statuses.map(s=>`<option ${filters.status===s?'selected':''}>${s}</option>`).join('')}</select></label><label>Schwierigkeit<select id="mission-difficulty"><option value="all">Alle Stufen</option>${['Entdecken','Üben','Anwenden'].map((s,i)=>`<option value="${i+1}" ${filters.difficulty===String(i+1)?'selected':''}>${i+1} · ${s}</option>`).join('')}</select></label><label class="mission-search">Suchen<input id="mission-search" type="search" value="${esc(filters.text)}" placeholder="Lernziel, Titel oder Aufgabentext"></label></div><div id="mission-summary" role="status" aria-live="polite"></div><div id="mission-list"></div><nav id="mission-pages" aria-label="Aufgabenseiten"></nav><details class="mission-method"><summary>So funktioniert der Lernweg</summary><p>Jede Klasse hat 240 neue Aufgabenvarianten in 42 Aufgabenfamilien und sechs zusätzliche Mitmachaufgaben. Entdecken bietet einen Einstieg, Üben festigt Strategien, Anwenden verbindet Wissen mit neuen Situationen. Die Stufen sind redaktionelle Anforderungen, keine gemessenen Fähigkeiten.</p><p>Der nächste Vorschlag beginnt bei einfachen Aufgaben. Zwei selbstständige Lösungen innerhalb einer Aufgabenfamilie öffnen bevorzugt die mittlere, vier die anspruchsvolle Stufe. Ein Tipp bleibt kostenlos. Jede vierte Empfehlung kann eine fällige Wiederholung aufgreifen (nach 1, 3, 7 oder 14 Tagen). Wiederholungen geben keine zusätzlichen Sterne.</p><p>„Begonnen“ heißt geöffnet, nicht falsch gelöst. „Selbstständig“ bedeutet in der App ohne Tipp oder Fehlversuch; Hilfe außerhalb der App ist unbekannt. „Mehrfach selbstständig“ heißt mindestens zwei entsprechende Lösungen, keine gesicherte Beherrschung. Frühere Fortschritte bleiben gespeichert; der neue Katalog beginnt mit eigenen Aufgabenkennungen.</p><p>Alle Daten bleiben in diesem Browser. Die Ansicht einer anderen Klasse ändert das Kinderprofil nicht. Beim Öffnen einer fremden Klassenstufe wird die Klassenwahl angezeigt.</p><p>Orientiert an den lokalen Lehrplänen und an <a href="https://educationendowmentfoundation.org.uk/education-evidence/guidance-reports/metacognition" target="_blank" rel="noopener">EEF: Selbstreguliertes Lernen</a> sowie <a href="https://ies.ed.gov/ncee/wwc/PracticeGuide/1" target="_blank" rel="noopener">IES: verteiltes Lernen und Abrufen</a>. Das System wurde nicht als Lernstandsdiagnostik oder Wirksamkeitsnachweis validiert.</p></details>`;
 for(const id of ['grade','subject','status','difficulty'])host.querySelector('#mission-'+id).onchange=e=>{filters[id]=id==='grade'?+e.target.value:e.target.value;page=0;list()};
 host.querySelector('#mission-search').oninput=e=>{filters.text=e.target.value;page=0;list()};
 host.onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.missionOpen){document.querySelector('#adult-dialog').close();Learning.openTask(b.dataset.missionOpen,filters.grade)}if(b.dataset.missionPage){page+=Number(b.dataset.missionPage);list();host.querySelector('#mission-summary').scrollIntoView({block:'nearest'})}};list();
}
function list(){const all=Learning.paths.flatMap(p=>p.items.filter(q=>q[7].grades.includes(filters.grade)).map(q=>({p,q,status:P.status(q,filters.grade)}))),solved=all.filter(x=>!['Offen','Begonnen'].includes(x.status)).length;
 const legacy=(LerndachsCurriculum.archived||[]).filter(({task:q})=>q[7].grades.includes(filters.grade)&&J.profile.done.includes(q[7].id)).length;
 const text=filters.text.toLocaleLowerCase('de');const rows=all.filter(({p,q,status})=>(filters.subject==='all'||p.subject===filters.subject)&&(filters.status==='all'||status===filters.status)&&(filters.difficulty==='all'||(q[7].difficulty||1)===+filters.difficulty)&&(!text||[q[1],q[2],q[7].skill,q[7].id].join(' ').toLocaleLowerCase('de').includes(text)));
 const max=Math.max(0,Math.ceil(rows.length/24)-1);page=Math.max(0,Math.min(page,max));
 host.querySelector('#mission-summary').textContent=`${solved} von ${all.length} gelöst · ${all.filter(x=>x.status==='Begonnen').length} begonnen · ${rows.length} Treffer${legacy?' · '+legacy+' archivierte Abschlüsse bleiben gespeichert':''}`;
 host.querySelector('#mission-list').innerHTML=rows.length?rows.slice(page*24,page*24+24).map(({p,q,status})=>{const m=q[7],r=P.record(q,filters.grade);return `<article class="mission-row"><div><small>${labels[p.subject]} · ${m.phase||'Mitmachen'} · ${m.response==='number'?'Zahl eingeben':m.response==='order'?'Schritte ordnen':m.type==='choice'?'Entscheiden':'In der Welt spielen'}</small><h3>${esc(q[1])}</h3><p>${esc(q[2])}</p><details><summary>Lernziel & Hinweise</summary><p>${esc(m.skill)}<br>${m.source==='media'?'KMK: Bildung in der digitalen Welt':esc(Learning.sources[m.source]?.title||m.source)+' · PDF-Seiten '+m.pages.join(', ')}${r?.lastAt?'<br>Zuletzt gelöst: '+new Date(r.lastAt).toLocaleDateString('de-DE')+(r.dueAt?'<br>Wiederholung ab: '+new Date(r.dueAt).toLocaleDateString('de-DE'):''):''}</p></details></div><div class="mission-row-action"><span class="mission-state ${status==='Offen'?'':'started'}">${esc(status)}</span><button data-mission-open="${m.id}">Öffnen →</button></div></article>`}).join(''):'<p class="mission-empty">Keine Aufgaben für diese Filter. Ändere die Auswahl oder den Suchtext.</p>';
 host.querySelector('#mission-pages').innerHTML=`<button data-mission-page="-1" ${page===0?'disabled':''}>← Zurück</button><span>Seite ${page+1} / ${max+1}</span><button data-mission-page="1" ${page===max?'disabled':''}>Weiter →</button>`;
}
window.LerndachsMissionOverview={render};
})();

