function sleepBehindSofa(){const sofa=Lernwelt.find('sofa')||{x:800,y:680},d=Lernwelt.find('dachs');if(d){d.x=sofa.x-60;d.y=sofa.y-180;d.s=.9;d.layer=2.9;d.pose='curled';J.render()}}
